	@ParameterizedTest
	@EnumSource(CallbackOutcome.class)
	void callbackOutcomePreservesSourceUntilExit(CallbackOutcome outcome, @TempDir Path dataDir) throws Exception {
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicInteger sourceCloses = new AtomicInteger();
		RuntimeException callbackFailure = new RuntimeException("native cancellation callback failed");
		RuntimeException cleanupFailure = new RuntimeException("native source cleanup failed");
		LmdbStore store = new LmdbStore(dataDir.toFile()) {
			@Override
			protected NotifyingSailConnection getConnectionInternal() throws SailException {
				return new LmdbStoreConnection(this) {
					@Override
					protected CloseableIteration<? extends Statement> getStatementsInternal(Resource subj, IRI pred,
							Value obj, boolean includeInferred, Resource... contexts) throws SailException {
						return new IterationWrapper<Statement>(super.getStatementsInternal(subj, pred, obj,
								includeInferred, contexts)) {
							@Override
							public boolean requestCancellation() {
								entered.countDown();
								try {
									assertTrue(release.await(10, TimeUnit.SECONDS));
								} catch (InterruptedException failure) {
									Thread.currentThread().interrupt();
									throw new SailException(failure);
								}
								if (outcome == CallbackOutcome.FAILED) {
									throw callbackFailure;
								}
								return outcome == CallbackOutcome.ACCEPTED;
							}

							@Override
							protected void handleClose() {
								try {
									super.handleClose();
								} finally {
									sourceCloses.incrementAndGet();
								}
								if (outcome == CallbackOutcome.FAILED) {
									throw cleanupFailure;
								}
							}
						};
					}
				};
			}
		};
		store.init();
		try (var worker = Executors.newSingleThreadExecutor()) {
			var values = SimpleValueFactory.getInstance();
			try (SailConnection seed = store.getConnection()) {
				seed.begin();
				seed.addStatement(values.createIRI("urn:cancel:s"), values.createIRI("urn:cancel:p"),
						values.createLiteral("o"));
				seed.commit();
			}
			LmdbGcTestMaintenance.awaitPostReady(store);
			try (SailConnection connection = store.getConnection();
					CloseableIteration<? extends Statement> result = connection.getStatements(null, null, null, false)) {
				assertTrue(result.hasNext(), "the native source must hold a live reader");
				CooperativeCancellation cancellation = assertInstanceOf(CooperativeCancellation.class, result);
				var request = worker.submit(cancellation::requestCancellation);
				try {
					assertTrue(entered.await(5, TimeUnit.SECONDS));
					result.close();
					assertEquals(0, sourceCloses.get(), "the admitted callback must retain its source");
				} finally {
					release.countDown();
				}
				if (outcome == CallbackOutcome.FAILED) {
					ExecutionException failure = assertThrows(ExecutionException.class, () -> request.get(5, TimeUnit.SECONDS));
					assertSame(callbackFailure, failure.getCause());
					assertEquals(List.of(cleanupFailure), List.of(failure.getCause().getSuppressed()));
				} else {
					assertEquals(outcome == CallbackOutcome.ACCEPTED, request.get(5, TimeUnit.SECONDS));
				}
				assertEquals(1, sourceCloses.get(), "callback exit must close the source exactly once");
				assertFalse(cancellation.requestCancellation());
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void concurrentCallbacksRetainTheSourceUntilBothExit(@TempDir Path dataDir) throws Exception {
		CountDownLatch firstEntered = new CountDownLatch(1);
		CountDownLatch secondEntered = new CountDownLatch(1);
		CountDownLatch releaseFirst = new CountDownLatch(1);
		CountDownLatch releaseSecond = new CountDownLatch(1);
		AtomicInteger requests = new AtomicInteger();
		AtomicInteger sourceCloses = new AtomicInteger();
		LmdbStore store = new LmdbStore(dataDir.toFile()) {
			@Override
			protected NotifyingSailConnection getConnectionInternal() throws SailException {
				return new LmdbStoreConnection(this) {
					@Override
					protected CloseableIteration<? extends Statement> getStatementsInternal(Resource subj, IRI pred,
							Value obj, boolean includeInferred, Resource... contexts) throws SailException {
						return new IterationWrapper<Statement>(super.getStatementsInternal(subj, pred, obj,
								includeInferred, contexts)) {
							@Override
							public boolean requestCancellation() {
								int invocation = requests.incrementAndGet();
								CountDownLatch entered = invocation == 1 ? firstEntered : secondEntered;
								CountDownLatch release = invocation == 1 ? releaseFirst : releaseSecond;
								entered.countDown();
								boolean interrupted = false;
								for (;;) {
									try {
										release.await();
										break;
									} catch (InterruptedException failure) {
										interrupted = true;
									}
								}
								if (interrupted) {
									Thread.currentThread().interrupt();
								}
								return true;
							}

							@Override
							protected void handleClose() {
								try {
									super.handleClose();
								} finally {
									sourceCloses.incrementAndGet();
								}
							}
						};
					}
				};
			}
		};
		store.init();
		try (var workers = Executors.newFixedThreadPool(2)) {
			var values = SimpleValueFactory.getInstance();
			try (SailConnection seed = store.getConnection()) {
				seed.begin();
				seed.addStatement(values.createIRI("urn:cancel:s"), values.createIRI("urn:cancel:p"),
						values.createLiteral("o"));
				seed.commit();
			}
			LmdbGcTestMaintenance.awaitPostReady(store);
			try (SailConnection connection = store.getConnection();
					CloseableIteration<? extends Statement> result = connection.getStatements(null, null, null, false)) {
				assertTrue(result.hasNext(), "the native source must hold a live reader");
				CooperativeCancellation cancellation = assertInstanceOf(CooperativeCancellation.class, result);
				var first = workers.submit(cancellation::requestCancellation);
				var second = workers.submit(() -> {
					assertTrue(firstEntered.await(5, TimeUnit.SECONDS));
					return cancellation.requestCancellation();
				});
				try {
					assertTrue(secondEntered.await(5, TimeUnit.SECONDS));
					result.close();
					assertEquals(0, sourceCloses.get(), "both callbacks still retain the source");
					releaseFirst.countDown();
					assertTrue(first.get(5, TimeUnit.SECONDS));
					assertEquals(0, sourceCloses.get(), "the second callback still retains the source");
					releaseSecond.countDown();
					assertTrue(second.get(5, TimeUnit.SECONDS));
					assertEquals(1, sourceCloses.get(), "the last callback drains the source once");
					assertFalse(cancellation.requestCancellation(), "a closed result declines later requests");
					assertEquals(2, requests.get());
				} finally {
					releaseFirst.countDown();
					releaseSecond.countDown();
				}
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void callbackArrivingAfterFinalCloseDrainIsDeclinedWithoutWaiting(@TempDir Path dataDir) throws Exception {
		CountDownLatch closeEntered = new CountDownLatch(1);
		CountDownLatch releaseClose = new CountDownLatch(1);
		AtomicBoolean armed = new AtomicBoolean();
		AtomicInteger requests = new AtomicInteger();
		AtomicInteger sourceCloses = new AtomicInteger();
		AtomicReference<Throwable> closeFailure = new AtomicReference<>();
		LmdbStore store = new LmdbStore(dataDir.toFile()) {
			@Override
			protected NotifyingSailConnection getConnectionInternal() throws SailException {
				return new LmdbStoreConnection(this) {
					@Override
					protected CloseableIteration<? extends Namespace> getNamespacesInternal() {
						return new IterationWrapper<Namespace>(new EmptyIteration<>()) {
							@Override
							public boolean requestCancellation() {
								requests.incrementAndGet();
								return true;
							}

							@Override
							protected void handleClose() {
								try {
									super.handleClose();
								} finally {
									sourceCloses.incrementAndGet();
								}
							}
						};
					}

					@Override
					protected void closeInternal() throws SailException {
						if (armed.get()) {
							closeEntered.countDown();
							boolean interrupted = false;
							for (;;) {
								try {
									releaseClose.await();
									break;
								} catch (InterruptedException failure) {
									interrupted = true;
								}
							}
							if (interrupted) {
								Thread.currentThread().interrupt();
							}
						}
						super.closeInternal();
					}
				};
			}
		};
		store.init();
		try (var workers = Executors.newFixedThreadPool(2)) {
			SailConnection connection = store.getConnection();
			CloseableIteration<? extends Namespace> result = connection.getNamespaces();
			armed.set(true);
			var closing = workers.submit(() -> {
				try {
					connection.close();
				} catch (Throwable failure) {
					closeFailure.set(failure);
				}
			});
			try {
				assertTrue(closeEntered.await(5, TimeUnit.SECONDS), "the final close drain must complete first");
				var request = workers.submit(assertInstanceOf(CooperativeCancellation.class, result)::requestCancellation);
				assertFalse(request.get(5, TimeUnit.SECONDS), "a final-drained connection cannot admit a callback");
				assertEquals(0, requests.get(), "the retired owner must not call its source");
			} finally {
				releaseClose.countDown();
				closing.get(5, TimeUnit.SECONDS);
				result.close();
			}
			assertInstanceOf(SailException.class, closeFailure.get());
			assertEquals("Connection closed before all iterations were closed.", closeFailure.get().getMessage());
			assertEquals(1, sourceCloses.get());
		} finally {
			store.shutDown();
		}
	}

	private enum ReentrantClose {
		CONNECTION, STORE, RESULT
	}

	@ParameterizedTest
	@EnumSource(ReentrantClose.class)
	void callbackCannotTearDownItsOwnNativeOwner(ReentrantClose closeTarget, @TempDir Path dataDir) {
		assertCallbackCannotTearDownItsOwnNativeOwner(closeTarget, dataDir, false);
	}

	@ParameterizedTest
	@EnumSource(ReentrantClose.class)
	void closeTimeCallbackCannotTearDownItsOwnNativeOwner(ReentrantClose closeTarget, @TempDir Path dataDir) {
		assertCallbackCannotTearDownItsOwnNativeOwner(closeTarget, dataDir, true);
	}

	private void assertCallbackCannotTearDownItsOwnNativeOwner(ReentrantClose closeTarget, Path dataDir,
			boolean closeResult) {
		AtomicReference<SailConnection> owner = new AtomicReference<>();
		AtomicReference<CloseableIteration<? extends Statement>> resultRef = new AtomicReference<>();
		AtomicReference<Throwable> refusal = new AtomicReference<>();
		AtomicInteger callbacks = new AtomicInteger();
		AtomicInteger sourceCloses = new AtomicInteger();
		AtomicInteger prematureCloses = new AtomicInteger();
		AtomicReference<LmdbStore> storeRef = new AtomicReference<>();
		LmdbStore store = new LmdbStore(dataDir.toFile()) {
			@Override
			protected NotifyingSailConnection getConnectionInternal() throws SailException {
				return new LmdbStoreConnection(this) {
					@Override
					protected CloseableIteration<? extends Statement> getStatementsInternal(Resource subj, IRI pred,
							Value obj, boolean includeInferred, Resource... contexts) throws SailException {
						return new IterationWrapper<Statement>(super.getStatementsInternal(subj, pred, obj,
								includeInferred, contexts)) {
							@Override
							public boolean requestCancellation() {
								callbacks.incrementAndGet();
								try {
									if (closeTarget == ReentrantClose.CONNECTION) {
										owner.get().close();
									} else if (closeTarget == ReentrantClose.STORE) {
										storeRef.get().shutDown();
									} else {
										resultRef.get().close();
									}
								} catch (Throwable failure) {
									refusal.set(failure);
								}
								if (!owner.get().isOpen() || sourceCloses.get() != 0) {
									prematureCloses.incrementAndGet();
								}
								return true;
							}

							@Override
							protected void handleClose() {
								try {
									super.handleClose();
								} finally {
									sourceCloses.incrementAndGet();
								}
							}
						};
					}
				};
			}
		};
		storeRef.set(store);
		store.init();
		try {
			var values = SimpleValueFactory.getInstance();
			try (SailConnection seed = store.getConnection()) {
				seed.begin();
				seed.addStatement(values.createIRI("urn:cancel:s"), values.createIRI("urn:cancel:p"),
						values.createLiteral("o"));
				seed.commit();
			}
			LmdbGcTestMaintenance.awaitPostReady(store);
			try (SailConnection connection = store.getConnection();
					CloseableIteration<? extends Statement> result = connection.getStatements(null, null, null, false)) {
				owner.set(connection);
				resultRef.set(result);
				assertTrue(result.hasNext(), "a live native source must be opened before cancellation");
				if (closeResult) {
					result.close();
				} else {
					assertTrue(assertInstanceOf(CooperativeCancellation.class, result).requestCancellation());
				}
				if (closeTarget == ReentrantClose.RESULT) {
					assertNull(refusal.get(), "the result may request its own deferred close");
				} else {
					assertNotNull(refusal.get(), "reentrant shutdown must be refused before teardown");
					assertInstanceOf(SailException.class, refusal.get());
					assertEquals(closeTarget == ReentrantClose.CONNECTION
							? "An active connection operation cannot close its own connection"
							: "An active Sail operation cannot shut down its own store", refusal.get().getMessage());
					assertNull(refusal.get().getCause());
				}
				assertEquals(0, prematureCloses.get(), "the callback must retain its live connection and source");
				assertEquals(1, callbacks.get());
			}
		} finally {
			store.shutDown();
		}
		assertEquals(1, sourceCloses.get(), "the source closes once after the callback exits");
	}

	@Test
	void closeTimeCallbackFailureKeepsDeferredCleanupFailureSuppressed(@TempDir Path dataDir) {
		RuntimeException callbackFailure = new RuntimeException("close-time cancellation failed");
		RuntimeException cleanupFailure = new RuntimeException("deferred source close failed");
		AtomicInteger callbacks = new AtomicInteger();
		AtomicInteger sourceCloses = new AtomicInteger();
		LmdbStore store = new LmdbStore(dataDir.toFile()) {
			@Override
			protected NotifyingSailConnection getConnectionInternal() throws SailException {
				return new LmdbStoreConnection(this) {
					@Override
					protected CloseableIteration<? extends Statement> getStatementsInternal(Resource subj, IRI pred,
							Value obj, boolean includeInferred, Resource... contexts) throws SailException {
						return new IterationWrapper<Statement>(super.getStatementsInternal(subj, pred, obj,
								includeInferred, contexts)) {
							@Override
							public boolean requestCancellation() {
								callbacks.incrementAndGet();
								assertEquals(0, sourceCloses.get(), "the callback must retain its source");
								throw callbackFailure;
							}

							@Override
							protected void handleClose() {
								try {
									super.handleClose();
								} finally {
									sourceCloses.incrementAndGet();
								}
								throw cleanupFailure;
							}
						};
					}
				};
			}
		};
		store.init();
		try {
			var values = SimpleValueFactory.getInstance();
			try (SailConnection seed = store.getConnection()) {
				seed.begin();
				seed.addStatement(values.createIRI("urn:cancel:s"), values.createIRI("urn:cancel:p"),
						values.createLiteral("o"));
				seed.commit();
			}
			LmdbGcTestMaintenance.awaitPostReady(store);
			try (SailConnection connection = store.getConnection();
					CloseableIteration<? extends Statement> result = connection.getStatements(null, null, null, false)) {
				assertTrue(result.hasNext(), "a live native source must be opened before close");
				assertSame(callbackFailure, assertThrows(RuntimeException.class, result::close));
				assertEquals(List.of(cleanupFailure), List.of(callbackFailure.getSuppressed()));
				assertEquals(1, callbacks.get());
				assertEquals(1, sourceCloses.get());
			}
		} finally {
			store.shutDown();
		}
	}

